public sealed class AnnualPlanningService(VirtualCompanyDbContext db,ICompanyMembershipContextResolver memberships,
 ITodayWorkspaceLensResolver lenses,ICompanyGoalQueryService goals,IQuarterlyPlanningService quarters,
 IAuthorizationService authorization,ICurrentUserAccessor user,IAuditEventWriter audit,IServiceProvider services,TimeProvider clock):IAnnualPlanningService
{
 public const string Governance="Annual approval records intent and budget governance. It does not authorize payments, postings, publication or customer commitments.";
 internal static string Hash(object value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(value))));
 private async Task<ResolvedCompanyMembershipContext> Require(Guid c,CancellationToken ct){var m=await memberships.ResolveAsync(c,ct)??throw new UnauthorizedAccessException();if(m.MembershipRole is not(CompanyMembershipRole.Owner or CompanyMembershipRole.Admin or CompanyMembershipRole.Manager))throw new UnauthorizedAccessException();var l=await lenses.ResolveAsync(c,"company",ct);if(l.ActiveLens!="company"||!l.AvailableLenses.Any(x=>x.Lens=="company"&&(x.IsPrimary||x.IsExecutiveOversight))||!(await authorization.AuthorizeAsync(user.Principal,c,CompanyPolicies.FinanceView)).Succeeded)throw new UnauthorizedAccessException("Company performance and Finance access are required.");return m;}
 public async Task<bool> CanReadApprovalAsync(Guid c,Guid id,CancellationToken ct){try{await Require(c,ct);var links=await db.Set<AnnualObjective>().AsNoTracking().Where(x=>x.CompanyId==c&&x.PlanId==id).Join(db.Set<QuarterlyObjective>().Where(x=>x.CompanyId==c),a=>new{Id=a.BaselineReviewId,a.GoalId},q=>new{Id=q.ReviewId,q.GoalId},(a,q)=>q.Id).ToListAsync(ct);var sources=await db.Set<QuarterlyMeasureLink>().AsNoTracking().Where(x=>x.CompanyId==c&&links.Contains(x.ObjectiveId)).Select(x=>x.SnapshotId).Distinct().ToListAsync(ct);foreach(var source in sources)if(!await services.GetRequiredService<IMonthlyReviewAccessService>().CanReadAsync(c,source,ct))return false;return true;}catch(UnauthorizedAccessException){return false;}}
 private async Task<PlanningPeriod> Period(Guid c,int y,CancellationToken ct){var config=await db.AccountingConfigurations.AsNoTracking().SingleOrDefaultAsync(x=>x.CompanyId==c,ct)??throw new ArgumentException("Configure the fiscal calendar before planning.");var z=await db.Companies.Where(x=>x.Id==c).Select(x=>x.Timezone).SingleAsync(ct);if(string.IsNullOrWhiteSpace(z))throw new ArgumentException("Configure the company timezone.");var a=QuarterlyPlanningCalculation.Period(y,1,config.FiscalYearStartMonth,config.FiscalYearStartDay,z,config.BaseCurrency,config.Version);var b=QuarterlyPlanningCalculation.Period(y,4,config.FiscalYearStartMonth,config.FiscalYearStartDay,z,config.BaseCurrency,config.Version);return a with{Quarter=0,EndUtc=b.EndUtc};}
 private async Task<IReadOnlyList<AnnualBudgetOption>> Budgets(Guid c,PlanningPeriod p,CancellationToken ct){if(p.StartDay!=1)return [];var local=TimeZoneInfo.ConvertTimeFromUtc(p.StartUtc,TimeZoneInfo.FindSystemTimeZoneById(p.Timezone));var start=new DateTime(local.Year,local.Month,1,0,0,0,DateTimeKind.Utc);var end=start.AddYears(1);var rows=await db.Budgets.AsNoTracking().Where(x=>x.CompanyId==c&&x.PeriodStartUtc>=start&&x.PeriodStartUtc<end).Join(db.FinanceAccounts.Where(x=>x.CompanyId==c&&x.AccountType=="expense"),b=>b.FinanceAccountId,a=>a.Id,(b,a)=>new{b,a.Code,a.Name}).OrderBy(x=>x.b.Id).Take(1001).ToListAsync(ct);if(rows.Count>1000)throw new ArgumentException("More than 1,000 budget rows cannot be represented completely.");return rows.Select(x=>new AnnualBudgetOption(x.b.Id,x.b.FinanceAccountId,x.Code+" · "+x.Name,DateTime.SpecifyKind(x.b.PeriodStartUtc,DateTimeKind.Utc),x.b.Version,x.b.Currency,x.b.Amount,x.b.CostCenterId,Hash(new{x.b.Id,x.b.FinanceAccountId,x.b.PeriodStartUtc,x.b.Version,x.b.Amount,x.b.Currency,x.b.CostCenterId,x.b.UpdatedUtc}))).ToArray();}
 public async Task<AnnualPlanningOptions> OptionsAsync(Guid c,int y,CancellationToken ct){await Require(c,ct);var p=await Period(c,y,ct);var q=await quarters.OptionsAsync(c,y,1,ct);var reviews=new List<QuarterReviewSummary>();for(int i=1;i<=4;i++)reviews.AddRange(await quarters.HistoryAsync(c,y,i,ct));return new(c,p,await goals.ListAsync(c,null,ct),q.Owners,reviews,await Budgets(c,p,ct),q.Initiatives);}
 public async Task<AnnualPlanPreview> PreviewAsync(Guid c,AnnualPlanInput input,CancellationToken ct){var o=await OptionsAsync(c,input.FiscalYear,ct);if(o.Period.StartDay!=1)throw new ArgumentException("Annual budget binding supports month-start fiscal years; partial-month allocation requires an explicit Finance model.");if(input.Objectives is null||input.Objectives.Count is <1 or >50||input.BudgetIds is null||input.BudgetIds.Count is <1 or >100||input.Allocations is null||input.Allocations.Count>200||string.IsNullOrWhiteSpace(input.Notes)||input.Notes.Length>4000||input.Objectives.DistinctBy(x=>x.GoalId).Count()!=input.Objectives.Count||input.BudgetIds.Distinct().Count()!=input.BudgetIds.Count)throw new ArgumentException("Provide distinct objectives, expense budget references and a bounded proposal rationale.");var views=new List<AnnualObjectiveView>();var blocks=new List<string>();
 foreach(var x in input.Objectives){var g=o.Goals.SingleOrDefault(g=>g.Id==x.GoalId)??throw new KeyNotFoundException("Native objective unavailable.");var owner=o.Owners.SingleOrDefault(v=>v.Id==x.OwnerUserId)??throw new ArgumentException("Each objective needs an active accountable member.");if(g.Version!=x.GoalVersion)throw new CompanyOperatingConcurrencyException("Native objective changed.");if(g.BaselineValue is null||g.MetricKey is null||g.MetricUnit!=x.Unit||g.StartUtc>=o.Period.EndUtc||g.TargetUtc<=o.Period.StartUtc||Math.Abs(x.Target)>999999999999m||decimal.Round(x.Target,4)!=x.Target)throw new ArgumentException("Objective period, metric unit and target must match the annual binding.");var source=await quarters.OpenAsync(c,x.BaselineReviewId,ct);if(source.Summary.FiscalYear!=input.FiscalYear||source.Review.Period.CalendarVersion!=o.Period.CalendarVersion||source.Review.Period.Timezone!=o.Period.Timezone||source.Review.Period.StartUtc<o.Period.StartUtc||source.Review.Period.EndUtc>o.Period.EndUtc)throw new ArgumentException("Baseline review must belong to the selected fiscal year.");var progress=source.Review.Objectives.SingleOrDefault(v=>v.Objective.GoalId==x.GoalId)??throw new ArgumentException("Baseline review does not contain this objective.");if(progress.Objective.GoalVersion!=x.GoalVersion||progress.Objective.Unit!=x.Unit||progress.Objective.Measures.Any(m=>m.MeasureKey!=g.MetricKey))throw new ArgumentException("Baseline objective version, unit and measure must agree with the annual target.");if(progress.Actual is null)throw new ArgumentException("Baseline actual is unavailable; obtain complete native quarterly evidence before binding an annual target.");if(x.Milestones is null||x.Milestones.Count!=4||x.Milestones.Select(m=>m.Quarter).Order().SequenceEqual(new[]{1,2,3,4})==false)throw new ArgumentException("Provide one milestone for each fiscal quarter.");foreach(var m in x.Milestones){var localStart=TimeZoneInfo.ConvertTimeFromUtc(o.Period.StartUtc,TimeZoneInfo.FindSystemTimeZoneById(o.Period.Timezone));var q=QuarterlyPlanningCalculation.Period(input.FiscalYear,m.Quarter,localStart.Month,localStart.Day,o.Period.Timezone,o.Period.Currency,o.Period.CalendarVersion);if(string.IsNullOrWhiteSpace(m.Title)||m.Title.Length>200||m.DueUtc.Kind!=DateTimeKind.Utc||m.DueUtc<q.StartUtc||m.DueUtc>=q.EndUtc)throw new ArgumentException("Milestones need titles and UTC dates inside their configured fiscal quarters.");}if(x.InitiativeIds is null||x.InitiativeIds.Count>50||x.InitiativeIds.Distinct().Count()!=x.InitiativeIds.Count||x.InitiativeIds.Any(id=>!o.Initiatives.Any(i=>i.Id==id&&i.GoalId==g.Id)))throw new ArgumentException("Dependencies must reference this objective's native initiatives.");var deps=o.Initiatives.Where(i=>x.InitiativeIds.Contains(i.Id)).SelectMany(i=>i.DependsOn.Select(d=>i.Title+" depends on "+(o.Initiatives.SingleOrDefault(v=>v.Id==d)?.Title??"unavailable native initiative"))).ToArray();views.Add(new(x,g.Name,owner.Name,g.MetricKey,g.BaselineValue.Value,QuarterlyPlanningCalculation.Progress(progress.Actual,g.BaselineValue.Value,x.Target),progress.EvidenceState,$"/dashboard?companyId={c}&period=quarter&year={input.FiscalYear}&quarter={source.Summary.Quarter}&review={source.Summary.Id}&lens=company",deps));}
 var budgets=input.BudgetIds.Select(id=>o.Budgets.SingleOrDefault(b=>b.Id==id)??throw new KeyNotFoundException("Native expense budget unavailable in this fiscal year.")).ToArray();if(budgets.Any(b=>b.Currency!=o.Period.Currency||b.Amount<0))throw new ArgumentException("Expense budget references must use the fiscal-year base currency and nonnegative expense amounts.");if(budgets.GroupBy(b=>(b.MonthUtc,b.AccountId,b.CostCenterId)).Any(g=>g.Count()>1))throw new ArgumentException("Select one budget version for each month/account/dimension.");
 foreach(var a in input.Allocations){if(!input.BudgetIds.Contains(a.BudgetId)||!o.Owners.Any(v=>v.Id==a.OwnerUserId)||a.Kind is not("objective" or "investment" or "reserve")||string.IsNullOrWhiteSpace(a.Title)||a.Title.Length>200||a.Amount<0||a.Amount>999999999999m||decimal.Round(a.Amount,2)!=a.Amount||a.Quarter is <1 or >4||a.GoalId.HasValue&&!input.Objectives.Any(x=>x.GoalId==a.GoalId)||a.Kind=="objective"&&!a.GoalId.HasValue)throw new ArgumentException("Allocations need a referenced budget, active owner, title, quarter, amount and objective where applicable.");}
 foreach(var a in input.Allocations){var b=budgets.Single(b=>b.Id==a.BudgetId);var nativeQuarter=((b.MonthUtc.Month-o.Period.StartMonth+12)%12)/3+1;if(a.Quarter!=nativeQuarter)throw new ArgumentException("Allocation quarter must agree with its native budget month in this fiscal calendar.");}
 foreach(var b in budgets){var total=input.Allocations.Where(a=>a.BudgetId==b.Id).Sum(a=>a.Amount);if(total!=b.Amount)blocks.Add($"{b.Account} {b.MonthUtc:yyyy-MM} ({b.Version}): {b.Amount} {b.Currency} budget; {total} allocated; difference {b.Amount-total}.");}
 var fp=Hash(new{c,o.Period,input,views,budgets});return new(c,o.Period,input,views,budgets,budgets.Sum(b=>b.Amount),input.Allocations.Sum(a=>a.Amount),blocks,fp);}
 private IQueryable<AnnualPlanVersion> Plans(Guid c)=>db.Set<AnnualPlanVersion>().Where(x=>x.CompanyId==c).Include(x=>x.Objectives).ThenInclude(x=>x.Milestones).Include(x=>x.Objectives).ThenInclude(x=>x.Dependencies).Include(x=>x.Budgets).Include(x=>x.Allocations).AsSplitQuery();
 public async Task<AnnualPlanDocument> SaveAsync(Guid c,SaveAnnualPlan cmd,CancellationToken ct){var member=await Require(c,ct);if(cmd.RequestId==Guid.Empty||cmd.ExpectedVersion<0)throw new ArgumentException("Stable request identity and expected version required.");var hash=Hash(new{cmd.Input,cmd.PreviousId,cmd.ExpectedVersion,cmd.ExpectedFingerprint});var repeat=await Plans(c).SingleOrDefaultAsync(x=>x.RequestId==cmd.RequestId,ct);if(repeat!=null){if(repeat.CommandHash!=hash||repeat.AuthorUserId!=member.UserId)throw new CompanyOperatingConcurrencyException("Request identity already used.");return await OpenAsync(c,repeat.Id,ct);}var p=await PreviewAsync(c,cmd.Input,ct);if(p.Fingerprint!=cmd.ExpectedFingerprint)throw new CompanyOperatingConcurrencyException("Planning sources changed. Preview again.");var last=await db.Set<AnnualPlanVersion>().Where(x=>x.CompanyId==c&&x.FiscalYear==cmd.Input.FiscalYear).OrderByDescending(x=>x.Version).FirstOrDefaultAsync(ct);if(last?.Id!=cmd.PreviousId||(last?.Version??0)!=cmd.ExpectedVersion)throw new CompanyOperatingConcurrencyException("Another annual revision was saved. Reload history.");var id=Guid.NewGuid();var r=new AnnualPlanVersion{Id=id,CompanyId=c,FiscalYear=p.Period.FiscalYear,Version=cmd.ExpectedVersion+1,PreviousId=cmd.PreviousId,RequestId=cmd.RequestId,AuthorUserId=member.UserId,SavedUtc=clock.GetUtcNow().UtcDateTime,StartUtc=p.Period.StartUtc,EndUtc=p.Period.EndUtc,Currency=p.Period.Currency,Timezone=p.Period.Timezone,CalendarVersion=p.Period.CalendarVersion,StartMonth=p.Period.StartMonth,StartDay=p.Period.StartDay,Notes=cmd.Input.Notes,Fingerprint=p.Fingerprint,CommandHash=hash};
 foreach(var v in p.Objectives){var x=v.Input;var source=await db.Set<QuarterlyReview>().AsNoTracking().SingleAsync(q=>q.CompanyId==c&&q.Id==x.BaselineReviewId,ct);var oid=Guid.NewGuid();r.Objectives.Add(new(){Id=oid,CompanyId=c,PlanId=id,GoalId=x.GoalId,GoalVersion=x.GoalVersion,OwnerUserId=x.OwnerUserId,OwnerName=v.Owner,Name=v.Name,MetricKey=v.MetricKey,Unit=x.Unit,Baseline=v.Baseline,Target=x.Target,BaselineReviewId=x.BaselineReviewId,SourceFingerprint=source.Fingerprint,Milestones=x.Milestones.Select(m=>new AnnualMilestone{Id=Guid.NewGuid(),CompanyId=c,ObjectiveId=oid,Quarter=m.Quarter,Title=m.Title,DueUtc=m.DueUtc}).ToList(),Dependencies=x.InitiativeIds.Select(i=>new AnnualDependency{Id=Guid.NewGuid(),CompanyId=c,ObjectiveId=oid,InitiativeId=i,Description=string.Join("; ",v.Dependencies)}).ToList()});}
 r.Budgets.AddRange(p.Budgets.Select(b=>new AnnualBudgetBinding{Id=Guid.NewGuid(),CompanyId=c,PlanId=id,BudgetId=b.Id,AccountId=b.AccountId,Account=b.Account,MonthUtc=b.MonthUtc,NativeVersion=b.Version,Currency=b.Currency,Amount=b.Amount,CostCenterId=b.CostCenterId,SourceFingerprint=b.Fingerprint}));r.Allocations.AddRange(cmd.Input.Allocations.Select(a=>new AnnualAllocation{Id=Guid.NewGuid(),CompanyId=c,PlanId=id,BudgetId=a.BudgetId,OwnerUserId=a.OwnerUserId,GoalId=a.GoalId,Kind=a.Kind,Title=a.Title,Amount=a.Amount,Quarter=a.Quarter}));db.Add(r);await Audit(c,id,member.UserId,"company.annual.drafted",ct);try{await db.SaveChangesAsync(ct);}catch(DbUpdateException ex) when(ex.InnerException?.Message.Contains("UNIQUE",StringComparison.OrdinalIgnoreCase)==true||ex.InnerException?.Message.Contains("duplicate",StringComparison.OrdinalIgnoreCase)==true){db.ChangeTracker.Clear();var winner=await Plans(c).AsNoTracking().SingleOrDefaultAsync(x=>x.RequestId==cmd.RequestId,ct);if(winner!=null&&winner.CommandHash==hash&&winner.AuthorUserId==member.UserId)return await OpenAsync(c,winner.Id,ct);throw new CompanyOperatingConcurrencyException("Another annual revision was saved. Reload history.");}return await OpenAsync(c,id,ct);}
 private static AnnualPlanInput Input(AnnualPlanVersion r)=>new(r.FiscalYear,r.Objectives.OrderBy(x=>x.GoalId).Select(x=>new AnnualObjectiveInput(x.GoalId,x.GoalVersion,x.OwnerUserId,x.BaselineReviewId,x.Target,x.Unit,x.Milestones.OrderBy(m=>m.Quarter).Select(m=>new AnnualMilestoneInput(m.Quarter,m.Title,m.DueUtc)).ToArray(),x.Dependencies.Select(d=>d.InitiativeId).Order().ToArray())).ToArray(),r.Budgets.Select(x=>x.BudgetId).Order().ToArray(),r.Allocations.OrderBy(x=>x.Id).Select(x=>new AnnualAllocationInput(x.BudgetId,x.OwnerUserId,x.GoalId,x.Kind,x.Title,x.Amount,x.Quarter)).ToArray(),r.Notes);
 private static AnnualPlanSummary Summary(AnnualPlanVersion r)=>new(r.Id,r.CompanyId,r.FiscalYear,r.Version,r.PreviousId,r.Status,r.StateRevision,r.AuthorUserId,r.SavedUtc,r.ApprovalId);
 public async Task<AnnualPlanDocument> OpenAsync(Guid c,Guid id,CancellationToken ct){await Require(c,ct);var r=await Plans(c).AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException("Annual plan unavailable.");if(!await CanReadApprovalAsync(c,id,ct))throw new UnauthorizedAccessException("Current retained source access is required for this annual version.");var current=await Period(c,r.FiscalYear,ct);var frozen=current with{StartUtc=r.StartUtc,EndUtc=r.EndUtc,Currency=r.Currency,Timezone=r.Timezone,CalendarVersion=r.CalendarVersion,StartMonth=r.StartMonth,StartDay=r.StartDay};var input=Input(r);var views=new List<AnnualObjectiveView>();foreach(var x in r.Objectives){decimal? actual=null;var state="Protected evidence unavailable";var sourceQuarter=await db.Set<QuarterlyReview>().Where(q=>q.CompanyId==c&&q.Id==x.BaselineReviewId).Select(q=>q.Quarter).SingleAsync(ct);try{var q=await quarters.OpenAsync(c,x.BaselineReviewId,ct);var v=q.Review.Objectives.Single(o=>o.Objective.GoalId==x.GoalId);if(q.Review.Fingerprint==x.SourceFingerprint){actual=v.Actual;state=v.EvidenceState;}}catch(UnauthorizedAccessException){}catch(KeyNotFoundException){}var i=input.Objectives.Single(o=>o.GoalId==x.GoalId);views.Add(new(i,x.Name,x.OwnerName,x.MetricKey,x.Baseline,QuarterlyPlanningCalculation.Progress(actual,x.Baseline,x.Target),state,$"/dashboard?companyId={c}&period=quarter&year={r.FiscalYear}&quarter={sourceQuarter}&review={x.BaselineReviewId}&lens=company",x.Dependencies.Select(d=>d.Description).Where(d=>d.Length>0).Distinct().ToArray()));}var budgets=r.Budgets.Select(b=>new AnnualBudgetOption(b.BudgetId,b.AccountId,b.Account,DateTime.SpecifyKind(b.MonthUtc,DateTimeKind.Utc),b.NativeVersion,b.Currency,b.Amount,b.CostCenterId,b.SourceFingerprint)).ToArray();var blocks=budgets.Where(b=>r.Allocations.Where(a=>a.BudgetId==b.Id).Sum(a=>a.Amount)!=b.Amount).Select(b=>$"Budget {b.Account}: allocations differ from {b.Amount} {b.Currency}.").ToList();var material=await ApprovalMaterialAsync(c,id,ct);if(material!=StoredMaterial(r))blocks.Add("A current source, owner or fiscal-calendar binding changed; create and preview a new revision before review.");var p=new AnnualPlanPreview(c,frozen,input,views,budgets,budgets.Sum(b=>b.Amount),r.Allocations.Sum(a=>a.Amount),blocks,r.Fingerprint);var before=r.PreviousId.HasValue?await Plans(c).AsNoTracking().SingleAsync(x=>x.Id==r.PreviousId,ct):null;return new(Summary(r),p,Changes(before,r),r.Status==AnnualPlanStates.Draft&&blocks.Count==0,Governance);}
 private static IReadOnlyList<string> Changes(AnnualPlanVersion? before,AnnualPlanVersion r){if(before==null)return["Initial annual targets, quarter milestones and expense budget allocation bindings."];var diffs=new List<string>();foreach(var x in r.Objectives){var b=before.Objectives.SingleOrDefault(o=>o.GoalId==x.GoalId);if(b==null){diffs.Add(x.Name+": added.");continue;}if(b.Target!=x.Target)diffs.Add($"{x.Name}: target {b.Target:0.####} → {x.Target:0.####} {x.Unit}.");if(b.OwnerUserId!=x.OwnerUserId)diffs.Add($"{x.Name}: owner {b.OwnerName} → {x.OwnerName}.");if(b.Baseline!=x.Baseline)diffs.Add($"{x.Name}: baseline {b.Baseline:0.####} → {x.Baseline:0.####}.");if(Hash(b.Milestones.OrderBy(m=>m.Quarter).Select(m=>new{m.Quarter,m.Title,m.DueUtc}))!=Hash(x.Milestones.OrderBy(m=>m.Quarter).Select(m=>new{m.Quarter,m.Title,m.DueUtc})))diffs.Add(x.Name+": quarter milestones changed.");}foreach(var x in before.Objectives.Where(b=>!r.Objectives.Any(o=>o.GoalId==b.GoalId)))diffs.Add(x.Name+": removed.");if(Hash(Input(before).Allocations.OrderBy(x=>x.Title))!=Hash(Input(r).Allocations.OrderBy(x=>x.Title)))diffs.Add("Objective, investment or reserve allocations changed; compare retained amounts below.");if(Hash(Input(before).BudgetIds)!=Hash(Input(r).BudgetIds))diffs.Add("Finance budget references changed.");return diffs.Count>0?diffs:["Proposal rationale or provenance revised; retained values are shown."];}
 public async Task<IReadOnlyList<AnnualPlanSummary>> HistoryAsync(Guid c,int y,CancellationToken ct){await Require(c,ct);_=await Period(c,y,ct);return(await db.Set<AnnualPlanVersion>().AsNoTracking().Where(x=>x.CompanyId==c&&x.FiscalYear==y).OrderByDescending(x=>x.Version).Take(50).ToListAsync(ct)).Select(Summary).ToArray();}
 private static string StoredMaterial(AnnualPlanVersion r)=>Hash(new{r.Fingerprint,r.CalendarVersion,r.StartUtc,r.EndUtc,r.Currency,r.Timezone,owners=r.Objectives.Select(x=>x.OwnerUserId).Concat(r.Allocations.Select(x=>x.OwnerUserId)).Distinct().Order(),goals=r.Objectives.OrderBy(x=>x.GoalId).Select(x=>new{x.GoalId,x.GoalVersion}),budgets=r.Budgets.OrderBy(x=>x.BudgetId).Select(x=>new{x.BudgetId,x.SourceFingerprint}),sources=r.Objectives.OrderBy(x=>x.GoalId).Select(x=>new{x.BaselineReviewId,x.SourceFingerprint})});
 public async Task<string> ApprovalMaterialAsync(Guid c,Guid id,CancellationToken ct){var r=await Plans(c).AsNoTracking().SingleAsync(x=>x.Id==id,ct);var p=await Period(c,r.FiscalYear,ct);var owners=r.Objectives.Select(x=>x.OwnerUserId).Concat(r.Allocations.Select(x=>x.OwnerUserId)).Distinct().ToArray();var active=await db.CompanyMemberships.Where(x=>x.CompanyId==c&&x.Status==CompanyMembershipStatus.Active&&x.UserId.HasValue&&owners.Contains(x.UserId.Value)).Select(x=>x.UserId.Value).Distinct().OrderBy(x=>x).ToListAsync(ct);var gs=await db.CompanyGoals.Where(x=>x.CompanyId==c).ToDictionaryAsync(x=>x.Id,ct);var bs=(await Budgets(c,p,ct)).ToDictionary(x=>x.Id);var qs=await db.Set<QuarterlyReview>().AsNoTracking().Where(x=>x.CompanyId==c).ToDictionaryAsync(x=>x.Id,ct);return Hash(new{r.Fingerprint,p.CalendarVersion,p.StartUtc,p.EndUtc,p.Currency,p.Timezone,owners=active.Order(),goals=r.Objectives.OrderBy(x=>x.GoalId).Select(x=>new{x.GoalId,GoalVersion=gs.GetValueOrDefault(x.GoalId)?.Version??-1}),budgets=r.Budgets.OrderBy(x=>x.BudgetId).Select(x=>new{x.BudgetId,SourceFingerprint=bs.GetValueOrDefault(x.BudgetId)?.Fingerprint??"missing"}),sources=r.Objectives.OrderBy(x=>x.GoalId).Select(x=>new{x.BaselineReviewId,SourceFingerprint=qs.GetValueOrDefault(x.BaselineReviewId)?.Fingerprint??"missing"})});}
 public async Task<AnnualPlanDocument> ReviewAsync(Guid c,Guid id,ReviewAnnualPlan cmd,CancellationToken ct){var m=await Require(c,ct);return await db.Database.CreateExecutionStrategy().ExecuteAsync(async()=>{await using var tx=await db.Database.BeginTransactionAsync(ct);var doc=await OpenAsync(c,id,ct);if(doc.Summary.StateRevision!=cmd.ExpectedStateRevision||doc.Plan.Fingerprint!=cmd.ExpectedFingerprint)throw new CompanyOperatingConcurrencyException("Annual review changed. Reload.");if(!doc.CanReview)throw new ArgumentException(string.Join(" ",doc.Plan.ReviewBlocks.DefaultIfEmpty("Only a draft can be reviewed.")));var r=await Plans(c).SingleAsync(x=>x.Id==id,ct);r.Review(clock.GetUtcNow().UtcDateTime);await Audit(c,id,m.UserId,"company.annual.reviewed",ct);await db.SaveChangesAsync(ct);await services.GetRequiredService<IApprovalRequestService>().CreateAsync(c,new("annual_plan_version",id,"user",m.UserId,"annual_plan_governance",new Dictionary<string,JsonNode?>{{"Amount",JsonValue.Create(doc.Plan.BudgetTotal)},{"Currency",JsonValue.Create(doc.Plan.Period.Currency)},{"annualFingerprint",JsonValue.Create(r.Fingerprint)},{"reason",JsonValue.Create(Governance)},{"rationaleSummary",JsonValue.Create(doc.Plan.Input.Notes)}},"owner"),ct);await tx.CommitAsync(ct);return await OpenAsync(c,id,ct);});}
 public async Task ApplyDecisionAsync(Guid c,Guid id,Guid approval,string status,CancellationToken ct){var actor=await Require(c,ct);var r=await Plans(c).SingleAsync(x=>x.Id==id,ct);r.Decide(approval,status,clock.GetUtcNow().UtcDateTime);await Audit(c,id,actor.UserId,"company.annual."+status,ct);}
 private Task Audit(Guid c,Guid id,Guid actor,string action,CancellationToken ct)=>audit.WriteAsync(new AuditEventWriteRequest(c,"user",actor,action,"annual_plan_version",id.ToString(),"succeeded",RationaleSummary:Governance),ct);
}










